int main() {
    string s;
    getline(cin, s);
    vector<string> tmp = split(s, ",");
    int n = tmp.size();
    vector<int> res(n, -1);
    vector<int> ans(n);
    for (int i = 0; i < n; i++) {
        ans[i] = stoi(tmp[i]);
    }
​
    stack<int> stk;
    // 使用栈处理， 遍历两次是为了处理环的问题
    for (int i = 0; i < 2 * n - 1; i++) {
        int j = i % n;
        // 栈中维持递减
        while (!stk.empty() && ans[j] > ans[stk.top()]) {
            int top = stk.top();
            stk.pop();
            res[top] = ans[j];
        }
        // 只有第一次遍历才会入栈
        if (i < n) {
            stk.push(j);
        } 
    }
​
    for (int i = 0; i < n; i++) {
        cout << res[i];
        if (i != n - 1) {
            cout << ",";
        }
    }
    return 0;
}

