public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        // 读取整行输入并按逗号拆分
        String[] tmp = scanner.nextLine().split(",");
        int n = tmp.length;
        int[] ans = new int[n];
        int[] res = new int[n];
        Arrays.fill(res, -1); // 初始化结果数组，默认值为 -1
​
        for (int i = 0; i < n; i++) {
            ans[i] = Integer.parseInt(tmp[i]);
        }
​
        Stack<Integer> stack = new Stack<>();
        // 遍历两次以处理循环数组
        for (int i = 0; i < 2 * n - 1; i++) {
            int j = i % n;
            // 维护单调递减栈
            while (!stack.isEmpty() && ans[j] > ans[stack.peek()]) {
                res[stack.pop()] = ans[j];
            }
            // 仅在第一次遍历时入栈
            if (i < n) {
                stack.push(j);
            }
        }
​
        // 输出结果
        for (int i = 0; i < n; i++) {
            System.out.print(res[i]);
            if (i != n - 1) {
                System.out.print(",");
            }
        }
    }
}
