package main
​
import (
    "bufio"
    "fmt"
    "os"
    "strconv"
    "strings"
)
​
func main() {
    // 读取输入
    reader := bufio.NewReader(os.Stdin)
    line, _ := reader.ReadString('\n')
    line = strings.TrimSpace(line)
​
    // 解析输入数据
    tmp := strings.Split(line, ",")
    n := len(tmp)
    ans := make([]int, n)
    res := make([]int, n)
​
    for i, v := range tmp {
        ans[i], _ = strconv.Atoi(v)
        res[i] = -1 // 初始化结果数组
    }
​
    stack := []int{}
    // 遍历两次处理循环数组
    for i := 0; i < 2*n-1; i++ {
        j := i % n
        // 维护单调递减栈
        for len(stack) > 0 && ans[j] > ans[stack[len(stack)-1]] {
            top := stack[len(stack)-1]
            stack = stack[:len(stack)-1]
            res[top] = ans[j]
        }
        // 仅第一次遍历时入栈
        if i < n {
            stack = append(stack, j)
        }
    }
​
    // 输出结果
    fmt.Println(strings.Trim(strings.Join(strings.Fields(fmt.Sprint(res)), ","), "[]"))
}
